{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "mdbase.app-settings 1.0.0 record contract view",
  "description": "The reserved fields every app settings record shares. Everything else in the record belongs to the app and is described by the app's own settings contract.",
  "type": "object",
  "required": ["app", "scope", "settings_version"],
  "properties": {
    "app": {
      "type": "string",
      "pattern": "^[a-z0-9]+([.-][a-z0-9]+)*$",
      "description": "The app whose clients honour these settings, such as tasknotes or dev.mdbase.reader."
    },
    "scope": {
      "enum": ["collection", "user"],
      "description": "Who the values apply to: everyone using the app in this collection, or one person."
    },
    "user": {
      "type": "string",
      "minLength": 1,
      "description": "A link to the mdbase.person record the values apply to. Present only when scope is user."
    },
    "settings_version": {
      "type": "integer",
      "minimum": 1,
      "description": "The version of the app's settings schema that last wrote the record. A client that does not understand it treats the settings as read-only."
    }
  },
  "allOf": [
    {
      "if": { "properties": { "scope": { "const": "user" } }, "required": ["scope"] },
      "then": { "required": ["user"] },
      "else": { "not": { "required": ["user"] } }
    }
  ],
  "additionalProperties": true
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "dev.mdbase.reader.settings 1.0.0",
  "description": "Collection-wide settings that every mdbase Reader client honours. Every field is optional and has a default, so a record with none of them behaves like no record at all.",
  "type": "object",
  "required": ["app", "scope", "settings_version"],
  "properties": {
    "app": {
      "const": "dev.mdbase.reader",
      "description": "Marks this record as mdbase Reader's settings."
    },
    "scope": {
      "const": "collection",
      "description": "These settings apply to everyone using Reader in this collection."
    },
    "settings_version": {
      "type": "integer",
      "minimum": 1,
      "description": "The version of these settings that last wrote the record. Reader 1 writes 1."
    },
    "source_name_template": {
      "type": "string",
      "minLength": 1,
      "maxLength": 500,
      "default": "{{ title | slug }}",
      "description": "A Knap template for the file name of a new source note, chapters included, without .md. A / starts a folder under sources/. Only new sources use it; existing files are never renamed."
    },
    "annotation_name_template": {
      "type": "string",
      "minLength": 1,
      "maxLength": 500,
      "default": "{{ id }}",
      "description": "A Knap template for the file name of a new annotation under annotations/, without .md. Only new annotations use it; existing files are never renamed."
    }
  },
  "additionalProperties": true
}
